```cpp
#include <iostream>
#include <fstream>
#include <string>
#include <map>
using namespace std;

int main() {
    ifstream plik("uczniowie.txt");
    map<int, int> cnt;
    string imie;
    int ocena;
    while (plik >> imie >> ocena) {
        cnt[ocena]++;
    }

    cout << "a) Liczba uczniow wg ocen:" << endl;
    for (auto &p : cnt) {
        cout << "   " << p.first << ": " << p.second << endl;
    }

    int maxOcena = cnt.begin()->first;
    int maxCnt = cnt.begin()->second;
    for (auto &p : cnt) {
        if (p.second > maxCnt) {
            maxCnt = p.second;
            maxOcena = p.first;
        }
    }
    cout << endl << "b) Najczestsza ocena: " << maxOcena << endl;
    return 0;
}
```

Weryfikacja:
- cnt[2]=1 (Henryk)
- cnt[3]=3 (Bob, Ela, Jan)
- cnt[4]=3 (Cysia, Filip, Iza)
- cnt[5]=3 (Ala, Darek, Gosia)
- Suma: 1+3+3+3 = 10 (OK)
- Max count = 3, a map iteruje rosnaco, wiec pierwsze 3 to dla klucza 3 -> najczestsza ocena: 3
